// Phase 3, G6 continued: the FIRST FULL INTER FRAME PIXELS. Reconstruct the
// WHOLE inter frame (all decoded blocks assembled into a full-frame Y/U/V RAM)
// bit-exact vs the conformant SW-reference decoder's pre-filter recon of
// frame 1, for two verified-decode streams:
//   * qt_50 : 18 blocks, ALL skip -> pure motion compensation, no residual.
//   * cq32  : 21 blocks, ONE non-skip BLOCK_16X16 carrying a TX_16X16 (V_DCT,
//             eob=4) luma residual.
//
// Per block, per plane, this mirrors SW `_motionComp` / `_subBlockChroma`
// geometry EXACTLY (plane origin + MV, 4:2:0 chroma subsampling of the MV,
// sub-8x8 chroma sub-block splitting, edge-replicated reference fetch) and
// performs the actual pixel math with the PROVEN Harbor HW kernels:
//   * sub-pel MC  -> HarborInterConvolve (8-tap regular, bit-exact vs SW
//                    `_convolve`). Integer-phase MC is a direct edge-clamped
//                    reference copy (identical to SW `_convolve` for sub==0).
//   * residual    -> HarborInvTxfm (the block's tx_size / tx_type), added +
//                    clipped.
// The per-block decode inputs (position/size/MV/skip/residual coeffs) are the
// bit-exact-verified outputs of the inter decode (HarborInterFrameWalk /
// inter_frame_decode_test), the reference plane is the SW keyframe recon
// (frame 0 = LAST). Each block is independent (inter has no intra-neighbour
// dependency), so assembly is a plain write into the frame RAM at its origin.

// Static AV1 spec geometry tables (from av1/common/common_data.h), inlined so
