/// Reference sample with libaom edge replication (matches SW `_refAt`).
int refAt(List<List<int>> p, int y, int x) {
  final h = p.length, w = p[0].length;
  final yy = y < 0 ? 0 : (y >= h ? h - 1 : y);
  final xx = x < 0 ? 0 : (x >= w ? w - 1 : x);
  return p[yy][xx];
}

int clip8(int v) => v < 0 ? 0 : (v > 255 ? 255 : v);

/// One motion-compensation region: a `w x h` output block at plane origin
/// (ox, oy) fetched from the reference at integer base (x0, y0) with fractional
/// phase (subX, subY) in 1/16-pel.
class _McOp {
  final int ox, oy, w, h, x0, y0, subX, subY;
  _McOp(
    this.ox,
    this.oy,
    this.w,
    this.h,
    this.x0,
    this.y0,
    this.subX,
    this.subY,
  );
}

// scale_chroma_bsize (4:2:0 only, which is all these streams use).
int _scaleChromaBsize420(int bs) {
  switch (bs) {
    case 0: // 4x4
    case 1: // 4x8
    case 2: // 8x4
      return 3; // -> 8x8
    case 16: // 4x16
      return 4; // -> 8x16
    case 17: // 16x4
      return 5; // -> 16x8
    default:
      return bs;
  }
}

/// Replicate SW `_motionComp` / `_subBlockChroma` geometry for one block+plane,
/// returning the list of MC regions to fetch (one for the normal path, several
/// for the sub-8x8 chroma split).
List<_McOp> blockMcOps(
  List<List<int>> mvRow0,
  List<List<int>> mvCol0,
  int r,
  int c,
  int bSize,
  int mvR,
  int mvC,
  int plane,
  int ssx,
  int ssy,
  int planeW,
  int planeH,
  int miRows,
  int miCols,
) {
  final sx = plane == 0 ? 0 : ssx, sy = plane == 0 ? 0 : ssy;
  final bw4 = _miSizeWide[bSize], bh4 = _miSizeHigh[bSize];
  final bw = _blockSizeWide[bSize], bh = _blockSizeHigh[bSize];
  final subBlock = bw < 8 || bh < 8;

  // sub-8x8 chroma: every constituent luma sub-block is inter here (all-inter
  // frame) -> is_sub8x8_inter true -> per-sub-block chroma prediction.
  if (plane > 0 && subBlock && (sx != 0 || sy != 0)) {
    final ops = <_McOp>[];
    final rowStart = (bh == 4 && sy == 1) ? -1 : 0;
    final colStart = (bw == 4 && sx == 1) ? -1 : 0;
    final omiR = r + rowStart, omiC = c + colStart;
    final geom = _scaleChromaBsize420(bSize);
    final b8w = (_miSizeWide[geom] * 4) >> sx;
    final b8h = (_miSizeHigh[geom] * 4) >> sy;
    final b4w = bw >> sx, b4h = bh >> sy;
    final chOx = (omiC * 4) >> sx, chOy = (omiR * 4) >> sy;
    for (var y = 0; y < b8h; y += b4h) {
      for (var x = 0; x < b8w; x += b4w) {
        final miR = omiR + (y ~/ b4h), miC = omiC + (x ~/ b4w);
        if (miR < 0 || miC < 0 || miR >= miRows || miC >= miCols) {
          continue;
        }
        var ox = chOx + x, oy = chOy + y;
        var w = b4w, h = b4h;
        if (ox + w > planeW) w = planeW - ox;
        if (oy + h > planeH) h = planeH - oy;
        if (w <= 0 || h <= 0) continue;
        final smvR = mvRow0[miR][miC], smvC = mvCol0[miR][miC];
        final mvqR = smvR << (1 - sy), mvqC = smvC << (1 - sx);
        final x0 = (ox * 16 + mvqC) >> 4, subX = mvqC & 15;
        final y0 = (oy * 16 + mvqR) >> 4, subY = mvqR & 15;
        ops.add(_McOp(ox, oy, w, h, x0, y0, subX, subY));
      }
    }
    return ops;
  }

  // Normal path.
  var omiR = r, omiC = c, geomBsize = bSize;
  if (plane > 0) {
    if (sy == 1 && (r & 1) == 1 && bh4 == 1) omiR = r - 1;
    if (sx == 1 && (c & 1) == 1 && bw4 == 1) omiC = c - 1;
    geomBsize = _scaleChromaBsize420(bSize);
  }
  final ox = (omiC * 4) >> sx, oy = (omiR * 4) >> sy;
  var pbw = (_miSizeWide[geomBsize] * 4) >> sx;
  var pbh = (_miSizeHigh[geomBsize] * 4) >> sy;
  if (ox + pbw > planeW) pbw = planeW - ox;
  if (oy + pbh > planeH) pbh = planeH - oy;
  if (pbw <= 0 || pbh <= 0) return const [];
  final mvqR = mvR << (1 - sy), mvqC = mvC << (1 - sx);
  final x0 = (ox * 16 + mvqC) >> 4, subX = mvqC & 15;
  final y0 = (oy * 16 + mvqR) >> 4, subY = mvqR & 15;
  return [_McOp(ox, oy, pbw, pbh, x0, y0, subX, subY)];
}

void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  /// Full inter-frame reconstruction: assemble every decoded block's motion
  /// compensation (+ residual) into a full-frame Y/U/V RAM, bit-exact vs SW
  /// pre-filter recon of frame 1.
  Future<void> runReconFrame({
    required List<List<int>> refY,
    required List<List<int>> refU,
    required List<List<int>> refV,
    required List<List<int>> preY,
    required List<List<int>> preU,
    required List<List<int>> preV,
    required List<List<int>> blocks,
    required List<List<int>> mvRow0,
    required List<List<int>> mvCol0,
    required List<List<int>> skipTxfm,
    required int ssx,
    required int ssy,
    required int numPlanes,
    required int miRows,
    required int miCols,
    required int expBlocks,
    required bool hasResidual,
    List<int>? residCoeff,
    int residTxSize = -1,
    int residTxType = 0,
  }) async {
    // Golden SW-reference pre-filter recon + per-block info (captured above).
    expect(
      blocks.length,
      equals(expBlocks),
      reason: 'decoded $expBlocks inter blocks',
    );
    final wY = preY[0].length, hY = preY.length;
    final wC = preU[0].length, hC = preU.length;

    // Frame RAM (full-frame Y/U/V), initialised to 0.
    final reconY = [for (var y = 0; y < hY; y++) List<int>.filled(wY, 0)];
    final reconU = [for (var y = 0; y < hC; y++) List<int>.filled(wC, 0)];
    final reconV = [for (var y = 0; y < hC; y++) List<int>.filled(wC, 0)];

    List<List<int>> reconPlane(int p) =>
        p == 0 ? reconY : (p == 1 ? reconU : reconV);
    List<List<int>> refPlane(int p) => p == 0 ? refY : (p == 1 ? refU : refV);
    int planeW(int p) => p == 0 ? wY : wC;
    int planeH(int p) => p == 0 ? hY : hC;

    // --- Pre-scan: collect the distinct (w,h) sizes of every SUB-PEL MC op so
    // one HarborInterConvolve is built per size (integer MC is a direct copy).
    final convSizes = <int>{}; // key = w*1000 + h
    for (final blk in blocks) {
      final r = blk[0], c = blk[1], bs = blk[2], mvR = blk[7], mvC = blk[8];
      for (var p = 0; p < numPlanes; p++) {
        for (final op in blockMcOps(
          mvRow0,
          mvCol0,
          r,
          c,
          bs,
          mvR,
          mvC,
          p,
          ssx,
          ssy,
          planeW(p),
          planeH(p),
          miRows,
          miCols,
        )) {
          if (op.subX != 0 || op.subY != 0) convSizes.add(op.w * 1000 + op.h);
        }
      }
    }

    final clk = SimpleClockGenerator(10).clk;

    // Build one convolve per needed size.
    final convs = <int, HarborInterConvolve>{};
    final convPatch = <int, Logic>{};
    final convFx = <int, Logic>{};
    final convFy = <int, Logic>{};
    for (final key in convSizes) {
      final w = key ~/ 1000, h = key % 1000;
      final conv = HarborInterConvolve(width: w, height: h);
      final patch = Logic(name: 'patch_${w}x$h', width: (w + 7) * (h + 7) * 8);
      final fx = Logic(name: 'fx_${w}x$h', width: 4);
      final fy = Logic(name: 'fy_${w}x$h', width: 4);
      conv.input('patch').srcConnection! <= patch;
      conv.input('frac_x').srcConnection! <= fx;
      conv.input('frac_y').srcConnection! <= fy;
      convs[key] = conv;
      convPatch[key] = patch;
      convFx[key] = fx;
      convFy[key] = fy;
    }

    // Build the residual inverse transform (single luma txb here).
    HarborInvTxfm? itx;
    Logic? itxReset, itxStart, itxCoeffs;
    int rTxSize = -1, rTw = 0, rTh = 0;
    List<int>? rCoeff;
    if (hasResidual) {
      rCoeff = residCoeff;
      rTxSize = residTxSize;
      final rTxType = residTxType;
      expect(rCoeff, isNotNull, reason: 'captured luma residual coeff buffer');
      rTw = _txSizeWide[rTxSize];
      rTh = _txSizeHigh[rTxSize];
      itx = HarborInvTxfm(txSize: rTxSize, txType: rTxType);
      itxReset = Logic(name: 'itx_reset');
      itxStart = Logic(name: 'itx_start');
      itxCoeffs = Logic(name: 'itx_coeffs', width: rTw * rTh * 16);
      itx.input('clk').srcConnection! <= clk;
      itx.input('reset').srcConnection! <= itxReset;
      itx.input('start').srcConnection! <= itxStart;
      itx.input('coeffs').srcConnection! <= itxCoeffs;
    }

    for (final conv in convs.values) {
      await conv.build();
    }
    if (itx != null) await itx.build();

    // Inject constant residual coeffs, reset the transform.
    if (itx != null) {
      itxReset!.inject(1);
      itxStart!.inject(0);
      var v = BigInt.zero;
      for (var i = 0; i < rTw * rTh; i++) {
        final cval = i < rCoeff!.length ? rCoeff[i] : 0;
        v |= BigInt.from(cval & 0xFFFF) << (i * 16);
      }
      itxCoeffs!.inject(v);
    }

    Simulator.setMaxSimTime(200000000);
    unawaited(Simulator.run());
    await clk.nextPosedge;
    if (itx != null) itxReset!.inject(0);

    // Run one sub-pel MC region through its convolve and write to the plane.
    Future<void> execConvOp(
      int p,
      _McOp op,
      List<List<int>> ref,
      List<List<int>> plane,
    ) async {
      final key = op.w * 1000 + op.h;
      final conv = convs[key]!;
      final pw = op.w + 7, ph = op.h + 7;
      var v = BigInt.zero;
      for (var pr = 0; pr < ph; pr++) {
        for (var pc = 0; pc < pw; pc++) {
          final s = refAt(ref, op.y0 + pr - 3, op.x0 + pc - 3);
          v |= BigInt.from(s & 0xFF) << ((pr * pw + pc) * 8);
        }
      }
      convPatch[key]!.inject(v);
      convFx[key]!.inject(op.subX);
      convFy[key]!.inject(op.subY);
      await clk.nextPosedge;
      final pred = conv.output('pred').value;
      for (var y = 0; y < op.h; y++) {
        for (var x = 0; x < op.w; x++) {
          plane[op.oy + y][op.ox + x] = pred
              .getRange((y * op.w + x) * 8, (y * op.w + x) * 8 + 8)
              .toInt();
        }
      }
    }

    // --- Motion compensation for every block/plane ---
    for (final blk in blocks) {
      final r = blk[0], c = blk[1], bs = blk[2], mvR = blk[7], mvC = blk[8];
      for (var p = 0; p < numPlanes; p++) {
        final ref = refPlane(p), plane = reconPlane(p);
        for (final op in blockMcOps(
          mvRow0,
          mvCol0,
          r,
          c,
          bs,
          mvR,
          mvC,
          p,
          ssx,
          ssy,
          planeW(p),
          planeH(p),
          miRows,
          miCols,
        )) {
          if (op.subX == 0 && op.subY == 0) {
            // Integer phase: direct edge-clamped reference copy.
            for (var y = 0; y < op.h; y++) {
              for (var x = 0; x < op.w; x++) {
                plane[op.oy + y][op.ox + x] = refAt(ref, op.y0 + y, op.x0 + x);
              }
            }
          } else {
            await execConvOp(p, op, ref, plane);
          }
        }
      }
    }

    // --- Residual add (non-skip luma block) via HarborInvTxfm ---
    if (itx != null) {
      // Locate the non-skip inter block (its luma origin).
      int? nsR, nsC, nsBs;
      for (final blk in blocks) {
        final r = blk[0], c = blk[1], bs = blk[2];
        if (skipTxfm[r][c] == 0) {
          nsR = r;
          nsC = c;
          nsBs = bs;
          break;
        }
      }
      expect(nsR, isNotNull, reason: 'a non-skip inter block exists');
      final ox = nsC! * 4, oy = nsR! * 4; // luma plane origin
      // TX_16X16 covers the whole 16x16 block as a single txb.
      expect(_blockSizeWide[nsBs!], equals(rTw));
      expect(_blockSizeHigh[nsBs], equals(rTh));
      itxStart!.inject(1);
      await clk.nextPosedge;
      itxStart.inject(0);
      var guard = 0;
      while (itx.output('done').value.toInt() != 1) {
        await clk.nextPosedge;
        if (++guard > 20000) fail('inv txfm timeout');
      }
      int sres(int v) => v >= 0x8000 ? v - 0x10000 : v;
      final residV = itx.output('residual').value;
      for (var yy = 0; yy < rTh; yy++) {
        for (var xx = 0; xx < rTw; xx++) {
          final rIdx = (yy * rTw + xx);
          final res = sres(residV.getRange(rIdx * 16, rIdx * 16 + 16).toInt());
          reconY[oy + yy][ox + xx] = clip8(reconY[oy + yy][ox + xx] + res);
        }
      }
    }

    // --- Verify the full frame against SW pre-filter ---
    var diffY = 0, diffU = 0, diffV = 0;
    for (var y = 0; y < hY; y++) {
      for (var x = 0; x < wY; x++) {
        if (reconY[y][x] != preY[y][x]) diffY++;
      }
    }
    for (var y = 0; y < hC; y++) {
      for (var x = 0; x < wC; x++) {
        if (reconU[y][x] != preU[y][x]) diffU++;
        if (reconV[y][x] != preV[y][x]) diffV++;
      }
    }
    expect(diffY, equals(0), reason: 'luma Y full-frame recon bit-exact');
    expect(diffU, equals(0), reason: 'chroma U full-frame recon bit-exact');
    expect(diffV, equals(0), reason: 'chroma V full-frame recon bit-exact');

    await Simulator.endSimulation();
  }

  test(
    'inter frame recon: qt_50 SKIP-only frame (pure MC) bit-exact vs SW',
    () async {
      await runReconFrame(
        refY: _refYQt50,
        refU: _refUQt50,
        refV: _refVQt50,
        preY: _preYQt50,
        preU: _preUQt50,
        preV: _preVQt50,
        blocks: _blocksQt50,
        mvRow0: _mvRow0Qt50,
        mvCol0: _mvCol0Qt50,
        skipTxfm: _skipTxfmQt50,
        ssx: 1,
        ssy: 1,
        numPlanes: 3,
        miRows: 16,
        miCols: 16,
        expBlocks: 18,
        hasResidual: false,
      );
    },
  );

  test(
    'inter frame recon: cq32 frame (MC + TX_16X16 residual) bit-exact vs SW',
    () async {
      await runReconFrame(
        refY: _refYCq32,
        refU: _refUCq32,
        refV: _refVCq32,
        preY: _preYCq32,
        preU: _preUCq32,
        preV: _preVCq32,
        blocks: _blocksCq32,
        mvRow0: _mvRow0Cq32,
        mvCol0: _mvCol0Cq32,
        skipTxfm: _skipTxfmCq32,
        ssx: 1,
        ssy: 1,
        numPlanes: 3,
        miRows: 16,
        miCols: 16,
        expBlocks: 21,
        hasResidual: true,
        residCoeff: _residCoeffCq32,
        residTxSize: 2,
        residTxType: 10,
      );
    },
  );
}
